/**
 * Commercial & ReStyle Prompt Preset Library
 *
 * 128 curated prompts organized by industry and style for batch
 * render processing (admin) and quick-start design inspiration (users).
 *
 * Categories:
 *   Commercial (25 prompts) - Real business names, photos, fleet branding
 *   ReStyle   (103 prompts) - Themed stylized wraps with texture & depth
 *     Original 30: Cyberpunk, Tactical, Racing, Nature, Cultural, Luxury,
 *                  Street Art, Chameleon, Inspired Essence
 *     Theme Restyle 30: Mythical, Geometric, Seasons, Music, Retro,
 *                       Wildlife, Cosmos, Steampunk, Botanical
 *     Signature Styles 8: Lowrider, Vintage, Race Livery, Floral,
 *                         Japanese, Tron, Designer
 *     Graphic Wraps 20: Angular Slash, Graffiti Art, Shattered,
 *                       Paint Splatter, Neon Block
 *     Vintage Heritage 15: Classic Muscle Stripes, Classic Truck/Off-Road,
 *                          Classic Sports Car/European
 */

export interface PromptPreset {
  id: string;
  prompt: string;
  category: "commercial" | "restyle";
  subcategory: string;
  tags: string[];
  name?: string;
  style?: string;
  vehicle?: { year: string; make: string; model: string };
  /**
   * CreatorMarket trade slug (matches marketplace_listings.trade_category).
   * Populated by the AI-prompt generator when a batch is scoped to a
   * single trade; left undefined for the static library presets, which
   * the user can categorize manually at publish time.
   */
  trade_category?: string | null;
}

