export const PROMPT_PRESETS: PromptPreset[] = [...COMMERCIAL_PROMPTS, ...RESTYLE_PROMPTS];

export function getPresetsByCategory(category: "commercial" | "restyle"): PromptPreset[] {
  return PROMPT_PRESETS.filter((p) => p.category === category);
}

export function getPresetsBySubcategory(subcategory: string): PromptPreset[] {
  return PROMPT_PRESETS.filter((p) => p.subcategory === subcategory);
}

export function getSubcategories(category: "commercial" | "restyle"): string[] {
  const subs = new Set(PROMPT_PRESETS.filter((p) => p.category === category).map((p) => p.subcategory));
  return Array.from(subs).sort();
}

export function searchPresets(query: string): PromptPreset[] {
  const q = query.toLowerCase();
  return PROMPT_PRESETS.filter(
    (p) =>
      p.prompt.toLowerCase().includes(q) ||
      p.subcategory.toLowerCase().includes(q) ||
      p.tags.some((t) => t.includes(q))
  );
}

/**
 * Returns `count` UNIQUE presets that haven't been used in recent batches.
 * Tracks used IDs in localStorage so each batch run gets fresh prompts.
 * Once every prompt in the pool has been used, the tracker resets.
 *
 * Guarantees: every preset in the returned array has a unique ID AND
 * unique prompt text. Shuffles available presets so consecutive batches
 * get variety even if localStorage is cleared between sessions.
 */
export function getRandomPresets(count: number, category?: "commercial" | "restyle"): PromptPreset[] {
  const pool = category ? getPresetsByCategory(category) : PROMPT_PRESETS;
  const storageKey = `restylepro_used_presets_${category || "all"}`;

  // Load previously used IDs
  let usedIds: string[] = [];
  try {
    const stored = localStorage.getItem(storageKey);
    if (stored) usedIds = JSON.parse(stored);
  } catch { /* ignore parse errors */ }

  // Filter to only unused prompts
  let available = pool.filter((p) => !usedIds.includes(p.id));

  // If not enough unused prompts remain, reset the tracker
  if (available.length < count) {
    usedIds = [];
    available = [...pool];
  }

  // Shuffle available pool so each batch gets variety even after a reset.
  // Uses Fisher-Yates for uniform distribution.
  const shuffled = [...available];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  // Pick `count` presets, guaranteeing unique prompt text
  const selected: PromptPreset[] = [];
  const seenPrompts = new Set<string>();
  for (const preset of shuffled) {
    if (selected.length >= count) break;
    const fingerprint = preset.prompt.slice(0, 120);
    if (seenPrompts.has(fingerprint)) continue;
    seenPrompts.add(fingerprint);
    selected.push(preset);
  }

  // Track these as used
  const newUsedIds = [...usedIds, ...selected.map((p) => p.id)];
  try {
    localStorage.setItem(storageKey, JSON.stringify(newUsedIds));
  } catch { /* localStorage full - still works, just won't track */ }

  console.log(
    `[PromptPresets] Selected ${selected.length} ${category || "mixed"} presets:`,
    selected.map((p) => `${p.id}: ${p.name || p.subcategory} - "${p.prompt.slice(0, 60)}…"`),
  );

  return selected;
}
